// ─────────── Helpers ───────────

export function preguntasPorLibro(libro: string): Pregunta[] {
  return PREGUNTAS.filter((p) => p.libro === libro);
}

export function preguntasPorTestamento(t: "AT" | "NT"): Pregunta[] {
  return PREGUNTAS.filter((p) => p.testamento === t);
}

/** Devuelve `n` preguntas aleatorias (shuffle Fisher-Yates) desde un pool. */
export function preguntasAleatorias(
  pool: Pregunta[],
  n: number,
  semilla?: number
): Pregunta[] {
  const arr = [...pool];
  // Si hay semilla, hacer shuffle determinístico (para SSR estable)
  let rnd: () => number;
  if (typeof semilla === "number") {
    let s = semilla;
    rnd = () => {
      s = (s * 1664525 + 1013904223) >>> 0;
      return s / 0xffffffff;
    };
  } else {
    rnd = Math.random;
  }
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr.slice(0, n);
}

/** Stats agregadas del banco de preguntas. */
export function statsTrivia() {
  const totalPreguntas = PREGUNTAS.length;
  const librosCubiertos = new Set(PREGUNTAS.map((p) => p.libro)).size;
  const at = PREGUNTAS.filter((p) => p.testamento === "AT").length;
  const nt = PREGUNTAS.filter((p) => p.testamento === "NT").length;
  return { totalPreguntas, librosCubiertos, at, nt };
}

/** Cuenta de preguntas disponibles por libro. */
export function conteoPorLibro(): Map<string, number> {
  const m = new Map<string, number>();
  for (const p of PREGUNTAS) {
    m.set(p.libro, (m.get(p.libro) ?? 0) + 1);
  }
  return m;
}

/** Cantidad mínima razonable de preguntas por ronda. */
export const PREGUNTAS_POR_RONDA = 10;
/** Segundos por pregunta. */
export const SEGUNDOS_POR_PREGUNTA = 15;
/** Vidas iniciales. */
export const VIDAS_INICIALES = 3;
